```csharp
using System;

class BubbleSort
{
    static void Main()
    {
        int[] arr = { 5, 2, 8, 1, 9, 3, 7 };

        Console.WriteLine("Original array: ");
        PrintArray(arr);

        int comparisons = BubbleSortAscending(arr);

        Console.WriteLine("Sorted array: ");
        PrintArray(arr);

        Console.WriteLine("Total comparisons: " + comparisons);
    }

    static int BubbleSortAscending(int[] arr)
    {
        int comparisons = 0;
        int n = arr.Length;

        for (int i = 0; i < n - 1; i++)
        {
            for (int j = 0; j < n - i - 1; j++)
            {
                comparisons++; // Increment comparisons for each comparison made

                if (arr[j] > arr[j + 1])
                {
                    // Swap arr[j] and arr[j+1]
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }

        return comparisons;
    }

    static void PrintArray(int[] arr)
    {
        foreach (int num in arr)
        {
            Console.Write(num + " ");
        }

        Console.WriteLine();
    }
}
```

